.report-actions{display:flex;justify-content:space-between;margin-bottom:16px}.product-print-report{padding:28px}.report-brand{display:flex;justify-content:space-between;border-bottom:2px solid #17583f;padding-bottom:18px}.report-brand img{width:190px;max-height:70px;object-fit:contain;object-position:left}.report-brand p,.report-title p{color:#718078}.report-title{margin:22px 0}.report-title h1{margin:0}.report-kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.report-kpis article,.price-comparison article{padding:14px;border:1px solid #dfe5df;border-radius:11px;background:#f8faf7;display:flex;flex-direction:column;gap:6px}.report-kpis span{font-size:10px;text-transform:uppercase;color:#718078}.report-kpis strong{font-size:17px}.report-kpis small{color:#718078}.report-kpis .collected{background:#e7f5eb}.report-kpis .credit{background:#fff5df}.report-kpis .due{background:#fff0ee}.report-kpis .due strong{color:#c83b32}.price-comparison{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:18px 0}.price-comparison h3,.price-comparison p{margin:0}.price-comparison strong{font-size:22px}.report-sales{margin-top:24px}.report-label{padding:5px 9px;border-radius:20px;font-weight:800;font-size:11px}.report-label.cash{background:#dcf1e2;color:#14723e}.report-label.credit{background:#ffedc9;color:#9a5a05}@media(max-width:900px){.report-kpis{grid-template-columns:repeat(2,1fr)}}@media print{.sidebar,.topbar,.report-actions{display:none!important}.app{margin:0!important;width:100%!important}.content{padding:0!important}.product-print-report{border:0!important;box-shadow:none!important;padding:0}.report-kpis{grid-template-columns:repeat(5,1fr)}.table-wrap{overflow:visible!important}table{font-size:9px}a{color:inherit;text-decoration:none}}
</style>
<?php page_end();
